CREATE OR REPLACE FUNCTION private.myday_stars()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare u uuid:=auth.uid();c uuid;department uuid;tz text;v_day date;mode text;week_start date;visible boolean;begin
 select company_id,department_id into c,department from public.profiles where id=u and active;if c is null then raise insufficient_privilege;end if;
 tz:=coalesce((select timezone from public.work_preferences where owner_id=u),'Europe/London');v_day:=(now() at time zone tz)::date;week_start:=date_trunc('week',v_day)::date;
 mode:=coalesce((select x.mode from private.myday_competition x where company_id=c),'off');visible:=coalesce((select s.visible from private.myday_star_consent s where owner_id=u and company_id=c),false);
 return jsonb_build_object('level_tasks',(select count(distinct task_id) from private.myday_star_awards where owner_id=u and company_id=c and task_id is not null and not voided),'mode',mode,'streak',private.myday_streak(u),'visible',visible,'today',coalesce((select sum(points) from private.myday_star_awards where owner_id=u and day=v_day and not voided),0),'week',coalesce((select sum(points) from private.myday_star_awards where owner_id=u and day>=week_start and day<week_start+7 and not voided),0),'history',coalesce((select jsonb_agg(to_jsonb(q)) from (select points,reason,created_at from private.myday_star_awards where owner_id=u and not voided order by created_at desc limit 30)q),'[]'),'teams',case when mode='off' or not visible then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(team)) from(select coalesce(d.name,'Company team') as name,round(avg(member.points),2) as average,count(*) as members from(select p.department_id,coalesce(sum(s.points),0) as points from public.profiles p join private.myday_star_consent consent on consent.owner_id=p.id and consent.company_id=c and consent.visible left join private.myday_star_awards s on s.owner_id=p.id and s.company_id=c and s.day>=week_start and s.day<week_start+7 and not s.voided where p.company_id=c and p.active group by p.id,p.department_id)member left join public.departments d on d.id=member.department_id and d.company_id=c group by d.name order by avg(member.points) desc,d.name)team),'[]') end,
 'own_rank',case when mode='off' or not visible then null else (select place from(select p.id,rank() over(order by coalesce(sum(s.points),0) desc) as place from public.profiles p join private.myday_star_consent consent on consent.owner_id=p.id and consent.company_id=c and consent.visible left join private.myday_star_awards s on s.owner_id=p.id and s.company_id=c and s.day>=week_start and s.day<week_start+7 and not s.voided where p.company_id=c and p.active and p.department_id is not distinct from department group by p.id having coalesce(sum(s.points),0)>0)ranked where id=u) end,
 'ranking',case when mode='off' or not visible then '[]'::jsonb else coalesce((select jsonb_agg(to_jsonb(q)) from(select p.id,p.full_name,sum(s.points) as stars from private.myday_star_awards s join public.profiles p on p.id=s.owner_id and p.active and p.company_id=c join private.myday_star_consent consent on consent.owner_id=p.id and consent.company_id=c and consent.visible where s.company_id=c and s.day>=week_start and s.day<week_start+7 and not s.voided and p.department_id is not distinct from department group by p.id,p.full_name having sum(s.points)>0 order by sum(s.points) desc,p.id limit 3)q),'[]') end);
end$function$
